-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
local addon_name = ...
LibStub("AceLocale-3.0"):NewLocale(addon_name, "enUS", true, true)
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.druid.balance.Name"] = "Balance"
L["rm.era.druid.balance.Description"] = "Balance from level 1 to 60, and the Druid default before talents or when no other premade fits. Starfire as the filler once learned (Wrath before that, Starfire first on a Nature's Grace proc), Moonfire and Insect Swarm kept on targets that will live while your mana is above 30%, Hurricane when three or more enemies are on you, Faerie Fire in a group, instants while moving, melee when out of mana. In Cat or Bear Form it gives the Feral advice instead. Reminders: Mark of the Wild, Thorns when solo, Omen of Clarity, Moonkin Form when you are in no form, Innervate, Nature's Grasp. Downranking Starfire, roots and target choice stay with you."
L["rm.era.druid.balance.icyveins.Name"] = "Balance (Icy Veins)"
L["rm.era.druid.balance.icyveins.Description"] = "Icy Veins' raid list for realms with the 16-debuff limit, an alternative to the recommended Balance premade, off by default: enable it and disable that one, or raise its priority. Starfire and nothing else, no Moonfire or Insect Swarm, Hurricane when three or more enemies are on you, Wrath only before Starfire is learned. Same reminders as the recommended premade."
L["rm.era.druid.feral.Name"] = "Feral"
L["rm.era.druid.feral.Description"] = "Feral cat and bear from level 10 when Feral is your main talent tree; your form decides which. Cat: stealth opener, Faerie Fire (Feral) kept up, Clearcasting spent on Shred, a finisher from four combo points (Rip before Ferocious Bite is learned and on long fights outside raids, Bite under 63 energy), Rake outside raids, Shred from behind or Claw when the target is on you, and a powershift (Cat Form again) when far short of energy with Furor 5/5 and mana to spare. Bear: Enrage when starved, Demoralizing Roar on packs and elites unless a warrior's Shout is up, Swipe on two or more and with spare rage, Faerie Fire (Feral) otherwise. Caster form: shift. Reminders: Maul every swing, Tiger's Fury before a pull, Manual Crowd Pummeler, Innervate, Frenzied Regeneration. Positioning stays with you."
L["rm.era.druid.feral.warcrafttavern.Name"] = "Feral (Warcraft Tavern, Rip and Bite)"
L["rm.era.druid.feral.warcrafttavern.Description"] = "Warcraft Tavern's powershifting list, an alternative to the recommended Feral premade, off by default: enable it and disable that one, or raise its priority. Rip at five combo points whenever it is missing, raids included, then Ferocious Bite from four combo points under 63 energy, Shred from behind, powershift when far short of energy. Bear and reminders as the recommended premade."
L["rm.era.druid.feral.warcrafttavern.casual.Name"] = "Feral (Warcraft Tavern, no powershifting)"
L["rm.era.druid.feral.warcrafttavern.casual.Description"] = "Warcraft Tavern's list without powershifting, an alternative to the recommended Feral premade, off by default: enable it and disable that one, or raise its priority. Build to five combo points with Shred (Claw from the front), then Rip on a target that will live, Tiger's Fury, Ferocious Bite; otherwise wait for energy. Bear and reminders as the recommended premade."
L["rm.era.druid.feral.wowhead.Name"] = "Feral (Wowhead raid bear)"
L["rm.era.druid.feral.wowhead.Description"] = "The cat of the recommended Feral premade with Wowhead's geared raid bear: Maul every swing (tab-Maul packs yourself), Swipe only with 60 rage to spare, Faerie Fire (Feral) otherwise, no Demoralizing Roar and no Enrage in combat. An alternative to the recommended Feral premade, off by default: enable it and disable that one, or raise its priority."
L["rm.era.druid.restoration.Name"] = "Restoration"
L["rm.era.druid.restoration.Description"] = "Restoration from level 10 when Restoration is your main talent tree. Heals your current friendly target: Healing Touch after Nature's Swiftness, Swiftmend below 40% on your own HoT, Rejuvenation and Regrowth kept rolling, Regrowth as the main heal with Improved Regrowth, full Healing Touch below 45% or on a Nature's Grace proc, rank 4 Healing Touch otherwise. On an enemy: Moonfire, Insect Swarm and Wrath. Silent in Cat or Bear Form. Reminders: Mark of the Wild, Omen of Clarity, Nature's Swiftness, Tranquility, Innervate, Rebirth, poison and curse removal. Choosing whom to heal stays with you."
L["rm.era.druid.restoration.warcrafttavern.Name"] = "Restoration (Warcraft Tavern)"
L["rm.era.druid.restoration.warcrafttavern.Description"] = "Warcraft Tavern's damage tiers, an alternative to the recommended Restoration premade, off by default: enable it and disable that one, or raise its priority. On your friendly target, with no HoT upkeep while damage is low: Swiftmend below 40%, rank 5 Regrowth below 50%, Rejuvenation and rank 3 Regrowth below 75%, full Healing Touch on a Nature's Grace proc, rank 3 Healing Touch below 90%. Reminders as the recommended premade."
L["rm.forever.druid.balance.Name"] = "Balance"
L["rm.forever.druid.balance.Description"] = "Balance from level 1 to 60, and the default for any Forever Druid no other premade fits (levels 1–9, untalented casters, solo Restoration). Pulls with Wrath; while moving, refreshes Moonfire, Insect Swarm and, in a group, Faerie Fire. Hurricane when three or more enemies are fighting you, then your own Moonfire and Insect Swarm, Starfire while Eclipse charges or Clearcasting are up, and Wrath; when you cannot afford Wrath it lets you melee. Health and mana are hidden from addons on Forever, so healing yourself and judging whether a target is worth a DoT are your call. Reminders: Mark of the Wild, Thorns while solo, Moonkin Form, a pre-pull Rejuvenation while solo, Nature's Grasp when a mob is on you, Innervate whenever it is ready in combat while solo. Form changes, crowd control, Barkskin and target choice stay with you. Built from level-30 beta guides; level 31–60 steps follow the class design and are untested."
L["rm.forever.druid.balance.tavern.Name"] = "Balance, Multi-DoT (Warcraft Tavern)"
L["rm.forever.druid.balance.tavern.Description"] = "Warcraft Tavern's Multi-DoT leveling style, an alternative to the recommended Balance premade, off by default: enable it and disable that one, or raise its priority. Pulls with Wrath, keeps your Moonfire and Insect Swarm on the target, roots it with Entangling Roots once both are running while another enemy is fighting you, then Wrath. No Starfire (the build skips Eclipse). Switching to the next enemy is up to you. Reminders: Mark of the Wild, Thorns while solo."
L["rm.forever.druid.feral.Name"] = "Feral, Cat and Bear"
L["rm.forever.druid.feral.Description"] = "Cat and Bear in one premade, chosen by your form; it takes over once Feral is your main talent tree (or has 11 points), or when you shift into Cat or Bear Form. Cat: Ravage or Shred from Prowl, Faerie Fire, Rip at four combo points, Ferocious Bite once Rip runs, Rake, then Shred when the target is not facing you (Claw otherwise). Bear: Faerie Fire and Feral Charge at range, Demoralizing Roar in a group or on two enemies, Primal Bite, Swipe on three or more, Lacerate, Swipe. In caster form it suggests Cat Form (Bear before you have Cat). Reminders: Maul whenever you can afford it in Bear Form, Enrage, Berserk on big pulls or elites, Innervate while solo, Mark of the Wild, Thorns. Health, energy, rage and mana are hidden from addons on Forever, so powershifting, Frenzied Regeneration and healing yourself are your call. Taunts, interrupts and positioning stay with you."
L["rm.forever.druid.restoration.Name"] = "Restoration"
L["rm.forever.druid.restoration.Description"] = "Group healing after Warcraft Tavern, once Restoration is your main talent tree with 11 points. Heals your current friendly target: Swiftmend on a target with your HoT, Wild Growth, Regrowth and Rejuvenation when missing, Healing Touch. Health and mana are hidden from addons on Forever, so the target you pick is the only sign of who needs healing. On a hostile target: Moonfire, Insect Swarm, Wrath. Reminders: Innervate in combat, Nature's Swiftness on a friendly target in combat, Remove Curse and Abolish Poison, Mark of the Wild; Tranquility is yours. You pick who to heal and the spell rank; solo Restoration uses the Balance premade."
L["rm.forever.druid.restoration.icyveins.Name"] = "Restoration, HoTs first (Icy Veins)"
L["rm.forever.druid.restoration.icyveins.Description"] = "Icy Veins' HoT-first healing, an alternative to the recommended Restoration premade, off by default: enable it and disable that one, or raise its priority. On your friendly target: Rejuvenation, then Regrowth when missing, Healing Touch only with both HoTs running, Swiftmend on a HoT target, then Wild Growth (health is hidden on Forever, so the target you pick decides who is healed). Innervate on cooldown. Otherwise the same reminders and hostile-target list as the Restoration premade."
L["rm.mop.druid.balance.Name"] = "Recommended"
L["rm.mop.druid.balance.Description"] = "Recommended for Balance from level 10, after Wowhead's Phase 5 list and simulator. Keeps Moonfire and Sunfire up and refreshes them inside the matching Eclipse, casts Starfall in Lunar Eclipse, Starsurge on Shooting Stars and on cooldown, Hurricane in Solar or Astral Storm in Lunar at five enemies, Starfire in and after Lunar and Wrath in and after Solar. Rotation Master cannot read Eclipse energy, so between Eclipses it keeps casting Starfire if Starfire was one of your last three casts, otherwise Wrath. Reminders: Mark of the Wild, Moonkin Form, Incarnation as an Eclipse starts and Celestial Alignment as one ends (on elites or long fights), Nature's Vigil, Force of Nature, Nature's Swiftness for Dream of Cenarius, Innervate, Solar Beam, Barkskin and Renewal when low. Wild Mushroom placement stays manual; the Detonate reminder is off by default. It stops while you cast, travel, are in Cat or Bear Form, or have no enemy targeted."
L["rm.mop.druid.feral.Name"] = "Recommended"
L["rm.mop.druid.feral.Description"] = "Recommended for Feral from level 10, after simulator and Wowhead's Phase 5 list. Puts you in Cat Form, opens from Prowl with Savage Roar and Ravage, keeps Savage Roar up, uses Predatory Swiftness for a Healing Touch at four or five combo points with Dream of Cenarius, Rip at five points (Ferocious Bite refreshes it below 25% health), Ferocious Bite at five points while Rip and Savage Roar both have six seconds left, Rake, Thrash on Clearcasting, Shred on Clearcasting or Berserk when the target is not attacking you (Rotation Master cannot tell whether you are behind it) and Mangle; Thrash and Swipe at four enemies. In Bear Form it gives a short tanking list. Reminders: Tiger's Fury under 35 energy, Berserk with it on elites or long fights, Incarnation, Force of Nature, Nature's Vigil, Skull Bash, Survival Instincts and Barkskin when low, Mark of the Wild. Bear- and Wrath-weaving, and Heart of the Wild, stay manual."
L["rm.mop.druid.feral.icyveins.Name"] = "Bite only in execute (Icy Veins)"
L["rm.mop.druid.feral.icyveins.Description"] = "Icy Veins' Feral order (Wowhead's Bite rule agrees), an alternative to the recommended Feral premade: enable it and disable that one, or raise its priority. Same opener, Savage Roar, Healing Touch and AoE, but combo points above 25% target health go only to Rip and Savage Roar: Ferocious Bite only refreshes Rip in execute (or spends five points before you learn Rip). Rake refreshes at two seconds, Thrash only on Clearcasting, and Berserk waits for 90 energy with Tiger's Fury at least 15 seconds away."
L["rm.mop.druid.guardian.Name"] = "Recommended"
L["rm.mop.druid.guardian.Description"] = "Recommended for Guardian tanks from level 10, after simulator and Wowhead's Phase 5 list. Puts you in Bear Form, pulls with Faerie Fire from range or Mangle, keeps Weakened Blows up with Thrash and Weakened Armor with Faerie Fire on elites, uses a Dream of Cenarius Healing Touch when hurt, Mangle on cooldown, Thrash and Swipe at three enemies, then Lacerate, Thrash and Faerie Fire. In Cat Form (Heart of the Wild) it gives a short damage list. Reminders: Savage Defense whenever it is down, Enrage for rage, Frenzied Regeneration when low or rage-capped, Maul above 90 rage or on Tooth and Claw, Barkskin while the target attacks you, Survival Instincts when low, Berserk and Incarnation on two enemies or a boss, Force of Nature, Nature's Vigil, Cenarion Ward, Skull Bash, Mark of the Wild. Taunting and Might of Ursoc stay manual (both reminders are off by default)."
L["rm.mop.druid.restoration.Name"] = "Recommended"
L["rm.mop.druid.restoration.Description"] = "Recommended for Restoration from level 10, after Wowhead's Phase 5 group healing. Heals your current friendly target, or you with no target; choosing whom to heal is up to you. Swiftmend on a target with your HoT when it is low, when Harmony has dropped, or into Wild Growth with Soul of the Forest; Wild Growth when three people nearby are hurt; instant Healing Touch on Nature's Swiftness; Regrowth on Clearcasting or a dying target; Rejuvenation; then Healing Touch and Nourish while standing still. An attackable target gets Moonfire and Wrath. Reminders: Lifebloom stacks and Ironbark on your focus (set the tank as focus), Wild Mushroom: Bloom on group damage, Force of Nature, Incarnation, Nature's Vigil, Nature's Swiftness, Innervate, Nature's Cure, Cenarion Ward, Barkskin, Mark of the Wild. Wild Mushroom placement, Tranquility and Genesis reminders are off by default."
L["rm.mop.druid.restoration.wowhead.Name"] = "Tank healing (Wowhead)"
L["rm.mop.druid.restoration.wowhead.Description"] = "Wowhead's single-target tank-healing order, an alternative to the recommended Restoration premade for when you are assigned to the tank: enable it and disable that one, or raise its priority. Keep the tank targeted: it keeps three Lifeblooms and Rejuvenation on it, uses Regrowth for heavy damage, Nourish for light damage, Healing Touch once Lifebloom and Rejuvenation are rolling and the tank is below half, and Swiftmend to keep it topped up. Same reminders as the recommended premade."
L["rm.mop.druid.unspecialized.Name"] = "Before a specialization"
L["rm.mop.druid.unspecialized.Description"] = "For levels 1 to 9, or any druid who has not chosen a specialization yet; the specialization premades take over once you pick one. In Cat Form it keeps Rake up, spends five combo points (or two on a dying target) on Ferocious Bite and builds with Mangle; in Bear Form it uses Mangle and Maul. Otherwise it pulls with Wrath, keeps Moonfire on targets that will last, casts Wrath (Moonfire while moving) and suggests Rejuvenation on yourself when you are below half health and alone. It stops while you cast, travel or have no enemy targeted."
L["rm.retail.druid.balance.Name"] = "Blizzard Assisted"
L["rm.retail.druid.balance.Description"] = "Recommended for Balance. Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, reminders for what Assisted Combat leaves to you: Celestial Alignment (or Incarnation) in combat, Solar Beam on an interruptible cast, Moonkin Form and Mark of the Wild between pulls, and Barkskin and your racial cooldown whenever they are ready in combat. Enemy casts are hidden in combat, so Solar Beam lights only where the game shows them; health is hidden on Retail, so when to use Barkskin is your call."
L["rm.retail.druid.balance.guide.Name"] = "Reference (Icy Veins, SimulationCraft and Wowhead)"
L["rm.retail.druid.balance.guide.Description"] = "Reference only, off by default: the guides' Balance priority. Your DoTs, Eclipse and procs are hidden from addons in Midnight combat, so it cannot run there; read it, or clone it to experiment. Astral Power is hidden on Retail, so Starsurge spends at its cost instead of before the cap. Pulls with Moonkin Form and Wrath. Sunfire and Moonfire when missing or about to fall off; Eclipse when neither is active (Lunar on three or more enemies, Solar otherwise); Starfall on Starweaver's Warp, Touch the Cosmos or packs; Starsurge on Starweaver's Weft or Touch the Cosmos; New, Half and Full Moon; Wild Mushroom in an Eclipse; Starsurge whenever you can afford it; Starfire in a Lunar Eclipse or on packs, else Wrath. Reminders: Celestial Alignment or Incarnation, Fury of Elune and Force of Nature before an Eclipse, Convoke in Celestial Alignment, Solar Beam, plus the utility reminders."
L["rm.retail.druid.feral.Name"] = "Blizzard Assisted"
L["rm.retail.druid.feral.Description"] = "Recommended for Feral. Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, reminders for what Assisted Combat leaves to you: Berserk (or Incarnation) in combat, Skull Bash on an interruptible cast, Survival Instincts, Barkskin and your racial cooldown whenever they are ready in combat, and Cat Form and Mark of the Wild between pulls. Enemy casts are hidden in combat, so the interrupt lights only where the game shows them; health is hidden on Retail, so when to use the defensives is your call."
L["rm.retail.druid.feral.guide.Name"] = "Reference (Icy Veins and SimulationCraft)"
L["rm.retail.druid.feral.guide.Description"] = "Reference only, off by default: the guides' Feral priority. Bleeds and procs are hidden in Midnight combat (combo points are not), so it cannot run there; energy is hidden on Retail. Opens with Cat Form, Prowl and Rake. Chomp; Ferocious Bite on Apex Predator's Craving; at five combo points Primal Wrath on two or more enemies, Rip when missing or in its last seconds, else Ferocious Bite, waiting for energy rather than building past five; below five, Rake when missing or about to fall off, Lunar Inspiration Moonfire, Swipe on three or more enemies, Shred. Reminders: Tiger's Fury whenever it is ready in combat, Berserk or Incarnation and Feral or Frantic Frenzy (at two points or fewer) in Tiger's Fury, Convoke in Tiger's Fury and Berserk with Rip up, Skull Bash, Survival Instincts, plus the utility reminders. Snapshotting is left to you."
L["rm.retail.druid.guardian.Name"] = "Blizzard Assisted"
L["rm.retail.druid.guardian.Description"] = "Recommended for Guardian. Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; Assisted Combat plays for damage only. Alongside it, reminders for what it leaves to you: Berserk (or Incarnation) and Convoke the Spirits in combat, Ironfur, Frenzied Regeneration, Survival Instincts, Barkskin and your racial cooldown whenever they are ready in combat, Skull Bash on an interruptible cast, and Bear Form and Mark of the Wild between pulls. Enemy casts are hidden in combat, so Skull Bash lights only where the game shows them; health and rage are hidden on Retail, so when to use the defensives is your call and Ironfur cannot wait for a rage threshold."
L["rm.retail.druid.guardian.guide.Name"] = "Reference (Icy Veins and Wowhead)"
L["rm.retail.druid.guardian.guide.Description"] = "Reference only, off by default: the guides' Guardian priority. Debuffs and procs are hidden in Midnight combat, so it cannot run there; rage and health are hidden on Retail, so the 80-rage Raze and Maul dump is left to you. Thrash and Mangle on cooldown, Red Moon on a single target, Moonfire when missing or on Galactic Guardian, Swipe. Reminders whenever they are ready in combat: Ironfur, Frenzied Regeneration, Survival Instincts; Bear Form between pulls; Berserk or Incarnation, Lunar Beam, Convoke, Heart of the Wild, Skull Bash, plus the utility reminders."
L["rm.retail.druid.guardian.simc.Name"] = "Defensive reference (SimulationCraft)"
L["rm.retail.druid.guardian.simc.Description"] = "Reference only, off by default: SimulationCraft's Guardian list, which spends rage on Ironfur first. Hidden combat data keeps it from running in Midnight combat, and rage is hidden on Retail, so its rage thresholds are left out. Ironfur in Berserk; Thrash when missing, about to fall off or under three stacks; Maul on Gory Fur; Thrash on three or more enemies; Mangle while Red Moon ticks; Red Moon; Mangle; Thrash; Moonfire; Swipe. Its cat-form weaving is left out. Reminders: Bear Form, Frenzied Regeneration, Survival Instincts, Berserk or Incarnation, Lunar Beam, Convoke, Skull Bash, plus the utility reminders."
L["rm.retail.druid.initial.Name"] = "Blizzard Assisted"
L["rm.retail.druid.initial.Description"] = "Recommended before you choose a specialization (while the game reports the Druid's initial specialization). Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, the reminders every Druid premade shares, each once you know its spell. When you choose a specialization at level 10, that specialization's premades take over."
L["rm.retail.druid.restoration.Name"] = "Blizzard Assisted with maintenance"
L["rm.retail.druid.restoration.Description"] = "Recommended for Restoration. With an enemy targeted it highlights Blizzard's Assisted Combat suggestion, Blizzard's Restoration damage list in cat or caster form. Otherwise it suggests Icy Veins' maintenance casts on your friendly target (or yourself): Lifebloom, Efflorescence in combat, Swiftmend on a Rejuvenation, Wild Growth in a group in combat, Regrowth on Clearcasting or five Abundance stacks, Rejuvenation when missing. Health and mana are hidden on Retail, so these follow the target you choose, not how hurt anyone is; your heals over time are hidden in Midnight combat, so the steps that read them wait there. Whom to heal, and every healing cooldown, is yours. Reminders: Innervate, Barkskin and your racial cooldown whenever they are ready in combat, Mark of the Wild between pulls."
L["rm.sod.druid.balance.Name"] = "Balance (SoD)"
L["rm.sod.druid.balance.Description"] = "Season of Discovery Balance from level 1 to 60, and the default for any Druid no other Season of Discovery premade fits. Starsurge whenever its buff is down, Sunfire and Moonfire on targets that will live, Starfire only when Starsurge or Lunar Eclipse empowers it, Wrath as the filler, Hurricane on six or more enemies (four with Gale Winds engraved), Insect Swarm only while moving. Runes are used as you engrave them. In Cat or Bear Form it gives the Feral advice. Reminders: Moonkin Form, Starfall, instant Healing Touch on a dying friend, curse and poison removal, Wild Growth on a hurt group, Innervate. Spreading DoTs to other targets stays with you."
L["rm.sod.druid.balance.icyveins.Name"] = "Balance (SoD, Icy Veins)"
L["rm.sod.druid.balance.icyveins.Description"] = "Icy Veins' Season of Discovery list, an alternative to the recommended Season of Discovery Balance premade, off by default: enable it and disable that one, or raise its priority. Starsurge on cooldown, Hurricane on four or more enemies (for Gale Winds), Starfire when Starsurge empowers it, Moonfire, Sunfire and Insect Swarm all kept up, Wrath as the filler. Reminders as the recommended premade."
L["rm.sod.druid.balance.wowhead.Name"] = "Balance (SoD, Wowhead)"
L["rm.sod.druid.balance.wowhead.Description"] = "Wowhead's Phase 8 list, an alternative to the recommended Season of Discovery Balance premade, off by default: enable it and disable that one, or raise its priority. Wrath to open, Starsurge on cooldown, Hurricane on six or more, Insect Swarm only while moving, Sunfire and Moonfire kept up, Wrath while your Sunfire has under 5 seconds when Elune's Fires is engraved to extend it, Starfire on Lunar Eclipse, Wrath otherwise. Reminders as the recommended premade."
L["rm.sod.druid.feral.Name"] = "Feral cat (SoD)"
L["rm.sod.druid.feral.Description"] = "Season of Discovery cat, chosen when Savage Roar is engraved (or Feral is your main tree without another legs rune). Faerie Fire (Feral) when none is up, Savage Roar, Swipe (Cat) on four or more enemies, the Mangle debuff, Clearcasting on Shred, Rip at five combo points while Savage Roar has 8 seconds left, Rake, Shred from behind or Mangle from the front, powershift with Furor 5/5, Faerie Fire refresh last. In Bear Form it gives the tank advice. Reminders: Tiger's Fury at 60 energy or less, Berserk with Tiger's Fury, Maul, Innervate. Positioning stays with you."
L["rm.sod.druid.restoration.Name"] = "Restoration (SoD)"
L["rm.sod.druid.restoration.Description"] = "Season of Discovery Restoration, chosen when Lifebloom is engraved (or Restoration is your main tree without another legs rune). Heals your current friendly target: instant Healing Touch after Nature's Swiftness or Fury of Stormrage, Wild Growth when two or more nearby are hurt, Swiftmend on your HoT for Efflorescence or below 40%, three Lifebloom stacks refreshed with a second left, Rejuvenation, Regrowth below 60%, Nourish, rank 4 Healing Touch. On an enemy: Sunfire, Moonfire, Wrath. Reminders: Tree of Life and Survival Instincts in heavy moments, Nature's Swiftness, Tranquility, Innervate, Rebirth, Revive, dispels. Choosing whom to heal stays with you."
L["rm.sod.druid.tank.Name"] = "Bear tank (SoD)"
L["rm.sod.druid.tank.Description"] = "Season of Discovery bear tank, chosen when Lacerate is engraved. Faerie Fire (Feral) or Sunfire (Bear) to pull from range, Lacerate before it drops, Mangle on cooldown, Lacerate, Swipe; on three or more enemies Mangle under Berserk and Swipe. In Cat Form it plays the cat list for off-tanking; in caster form it shifts to Bear. Reminders: Maul with 30 rage, Berserk, Survival Instincts, Frenzied Regeneration and Barkskin when low, Enrage between pulls, Demoralizing Roar on elites. Taunting and target choice stay with you."
L["rm.sod.druid.tank.simulator.Name"] = "Bear tank (SoD, simulator cat weave)"
L["rm.sod.druid.tank.simulator.Description"] = "Off by default; for experts whose gear also grants Savage Roar. The simulator Phase 7 cat weave: leave Bear for Cat when your Rake is down, keep Savage Roar and Rake up (Tiger's Fury, Mangle to build), then return to Dire Bear and play the tank list. Reminders as the recommended tank premade."
L["rm.tbc.druid.balance.Name"] = "Balance"
L["rm.tbc.druid.balance.Description"] = "Caster Balance from level 1 to 70, and the default for any Druid no other premade fits. Pulls with Starfire (Wrath before 20), Insect Swarm and Moonfire while moving, Faerie Fire in a group, Hurricane for three or more enemies, Moonfire when it has run out and you have 30% mana, Starfire on Nature's Grace, Wrath against a target in melee, then Starfire (Wrath before it is learned). No advice in Cat, Bear or travel forms. Reminders: Mark of the Wild, Thorns while solo, Omen of Clarity, Moonkin Form, Force of Nature on a long fight, Innervate when low."
L["rm.tbc.druid.feral.icyveins.Name"] = "Feral (Icy Veins, Warcraft Tavern & simulator)"
L["rm.tbc.druid.feral.icyveins.Description"] = "Cat and bear for the Feral tree, following your form. Cat: stealth opener (Pounce, Ravage or Shred), Faerie Fire (Feral), Rip at four combo points on a target that lives, Ferocious Bite between Rips without Clearcasting, Mangle kept up, Shred from behind or Mangle/Claw when the target is on you. Bear: Faerie Fire, Lacerate saved before it drops, Demoralizing Roar unless a warrior's Shout is up, Swipe for packs, Mangle, five Lacerates, Swipe. In caster form it suggests Cat (or Bear) Form. Reminders: Mark, Thorns, Omen, Maul with spare rage, Tiger's Fury before a pull, Frenzied Regeneration. Powershifting is an optional step that starts off (it needs a powershift macro)."
L["rm.tbc.druid.feral.wowhead.Name"] = "Feral (Wowhead)"
L["rm.tbc.druid.feral.wowhead.Description"] = "Wowhead's Feral, an alternative to the recommended Icy Veins Feral premade, off by default: enable it and disable that one, or raise its priority. Rip whenever it is down at four combo points and Ferocious Bite only on a target about to die (no bite-weaving); bears spend free global cooldowns on Lacerate before Swipe. Innervate when a cat runs low on mana. Otherwise the same as the Icy Veins variant."
L["rm.tbc.druid.restoration.Name"] = "Restoration"
L["rm.tbc.druid.restoration.Description"] = "Healing for the Restoration tree on your friendly target (or yourself): Healing Touch after Nature's Swiftness, Swiftmend a dying target that has your Rejuvenation or Regrowth, three rolling Lifeblooms in combat, Rejuvenation and Regrowth when missing, then Regrowth in Tree of Life or Healing Touch outside it. A hostile target gets Moonfire and Wrath for soloing. Reminders: Mark, Omen, Tree of Life, Nature's Swiftness, Tranquility, Innervate and Rebirth. Choosing whom to heal and downranking stay with you."
